oxy_webhelp_navlinks = {"arch_older_cdm_functionality-d39307e9997":{"topics":[{"title":"Container-level immutability for Azure archival locations","shortdesc":"<p class=\"shortdesc\">Azure archival locations created for Rubrik clusters running Rubrik CDM versions         earlier than 9.1 use the container-level immutability feature of Azure storage         containers and require manual configuration of immutability settings when creating         the archival location in <span class=\"ph\">RSC<\/span>.<\/p>","href":"archival\/azr_container_immutability.html","attributes":{"data-id":"azr_container_immutability"},"menu":{"hasChildren":false},"tocID":"azr_container_immutability-d39307e10008","next":"azr_container_immutability-d39307e10008"},{"title":"Azure archival immutability settings for CDM versions earlier than 9.1","shortdesc":"<p class=\"shortdesc\">When you create an Azure archival location for Rubrik clusters running Rubrik         CDM versions earlier than 9.1, you can enable the immutability setting for the archival         location to protect the archived data from changes for a specified time         period.<\/p>","href":"archival\/arch_azure_immutability_settings.html","attributes":{"data-id":"arch_azure_immutability_settings"},"menu":{"hasChildren":false},"tocID":"arch_azure_immutability_settings-d39307e10033","topics":[]},{"title":"Azure Archive tiering options","shortdesc":"<p class=\"shortdesc\">You can configure archive tiering for Azure archival locations to move older data to         the Archive tier based on an SLA Domain policy.<\/p>","href":"archival\/azure_archive_tiering.html","attributes":{"data-id":"azure_archive_tiering"},"menu":{"hasChildren":false},"tocID":"azure_archive_tiering-d39307e10044","next":"azure_archive_tiering-d39307e10044"},{"title":"Bucket-level immutability for Amazon S3","shortdesc":"<p class=\"shortdesc\">Amazon S3 archival locations on Rubrik clusters running Rubrik CDM versions earlier         than 9.3.1 can use bucket-level immutability of Amazon S3 storage.<\/p>","href":"archival\/aws_s3_bucket_level_immutability.html","attributes":{"data-id":"aws_s3_bucket_level_immutability"},"menu":{"hasChildren":false},"tocID":"aws_s3_bucket_level_immutability-d39307e10105","topics":[]},{"title":"Amazon S3 bucket-level immutability lock periods","shortdesc":"<p class=\"shortdesc\">Immutability lock periods for Amazon S3 archival locations with bucket-level         immutability.<\/p>","href":"archival\/amazon_s3_bucket_level_immu_lck_periods.html","attributes":{"data-id":"amazon_s3_bucket_level_immu_lck_periods"},"menu":{"hasChildren":false},"tocID":"amazon_s3_bucket_level_immu_lck_periods-d39307e10116","topics":[]},{"title":"Amazon S3 immutability settings","shortdesc":"<p class=\"shortdesc\">The advanced settings configuration of an Amazon S3 archival location includes an         option to enable bucket-level immutability. Amazon S3 archival locations created for Rubrik         clusters running Rubrik CDM version 9.3.1 and later support object-level immutability, which is always enabled.<\/p>","href":"archival\/arch_s3_immutability_setting.html","attributes":{"data-id":"arch_s3_immutability_setting"},"menu":{"hasChildren":false},"tocID":"arch_s3_immutability_setting-d39307e10127","topics":[]},{"title":"S3-compatible archival locations with bucket-level immutability","shortdesc":"<p class=\"shortdesc\">S3-compatible archival locations on Rubrik clusters running Rubrik CDM versions         earlier than 9.4.0-p1 can use bucket-level immutability.<\/p>","href":"archival\/amazon_s3_comp_arch_loc_bli.html","attributes":{"data-id":"amazon_s3_comp_arch_loc_bli"},"menu":{"hasChildren":false},"tocID":"amazon_s3_comp_arch_loc_bli-d39307e10138","topics":[]},{"title":"Creating S3-compatible archival locations with bucket-level immutability","shortdesc":"<p class=\"shortdesc\">Add an Amazon S3-compatible archival location with bucket-level immutability to         enable integration between the object storage and <span class=\"ph\">RSC<\/span>.<\/p>","href":"archival\/adding_s3_comp_arch_loc_bli.html","attributes":{"data-id":"adding_s3_comp_arch_loc_bli"},"menu":{"hasChildren":false},"tocID":"adding_s3_comp_arch_loc_bli-d39307e10149","topics":[]},{"title":"IBM COS archival locations","shortdesc":"<p class=\"shortdesc\">         <span class=\"ph\">RSC<\/span> supports IBM Cloud Object Storage as an archival location         for which you can configure immutability.<\/p>","href":"archival\/ibm_cos_archival_locations.html","attributes":{"data-id":"ibm_cos_archival_locations"},"menu":{"hasChildren":false},"tocID":"ibm_cos_archival_locations-d39307e10163","next":"ibm_cos_archival_locations-d39307e10163"},{"title":"Dell ECS archival location","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports Dell ECS Object Store as an archival location with bucket-level immutability for archiving encrypted data.<\/p>","href":"archival\/dell_ecs_arch_loc.html","attributes":{"data-id":"dell_ecs_arch_loc"},"menu":{"hasChildren":false},"tocID":"dell_ecs_arch_loc-d39307e10224","next":"dell_ecs_arch_loc-d39307e10224"},{"title":"NetApp StorageGRID archival locations","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports using NetApp StorageGRID as archival         locations for encrypted data. For data stored in NetApp StorageGRID archival         locations, Rubrik provides bucket-level immutability.<\/p>","href":"archival\/netapp_sg_arch_loc.html","attributes":{"data-id":"netapp_sg_arch_loc"},"menu":{"hasChildren":false},"tocID":"netapp_sg_arch_loc-d39307e10288","next":"netapp_sg_arch_loc-d39307e10288"}]}};